function treasureActivityActive(question=state.active){const boss=state.v5?.boss;return question?.silentTesting===true||question?.bossCourseStage!=null||boss?.status==='active';}
function grantTreasureReward(record){ensureV5();const amount=Math.max(0,Math.round(Number(record?.amount)||0));if(!amount)return 0;const stage=Math.max(0,Math.min(stages.length-1,Number(record?.stage)||0));addStoneChange(amount,Math.min(gemTiers.length-1,stage+5));state.v5.chests=Number(state.v5.chests||0)+1;state.v5.missions.chests=Number(state.v5.missions.chests||0)+1;state.v5.lastChestAt=Date.now();return amount;}
function chestReward(question=state.active){ensureV5();const record={amount:chestRewardAmount(),stage:selectedStageIndex(),earnedAt:Date.now()};if(treasureActivityActive(question)){state.v5.deferredTreasures.push(record);save();return{amount:record.amount,deferred:true};}grantTreasureReward(record);save();showChest(record.amount);return{amount:record.amount,deferred:false};}
function releaseDeferredTreasures(announce=true,label='Treasure received!'){ensureV5();const queued=[...state.v5.deferredTreasures];if(!queued.length)return{amount:0,count:0};state.v5.deferredTreasures=[];const amount=queued.reduce((sum,record)=>sum+grantTreasureReward(record),0);save();if(announce&&amount)showChest(amount,queued.length,label);return{amount,count:queued.length};}
function showChest(amount,count=1,label='Treasure found!'){let el=document.getElementById('v5Treasure');if(!el){el=document.createElement('div');el.id='v5Treasure';el.className='v5-treasure';document.body.appendChild(el);}el.innerHTML=`<div class="v5-chest">🎁</div><strong>${label}</strong><span>${count>1?`${count} treasures · `:''}+${amount.toLocaleString()} Nuggets</span>`;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200);}
function recordExternalCourseAnswer(options={}){
 ensureV5();const correct=options.correct===true,stage=Math.max(0,Math.min(stages.length-1,Number(options.stage)||0)),review=options.review===true,deferTreasure=options.deferTreasure===true;state.sessionAnswered=Number(state.sessionAnswered||0)+1;if(correct)state.sessionCorrect=Number(state.sessionCorrect||0)+1;state.streak=correct?Number(state.streak||0)+1:0;state.bestStreak=Math.max(Number(state.bestStreak||0),state.streak);state.v5.missions.answered=Number(state.v5.missions.answered||0)+1;if(review)state.v5.missions.reviews=Number(state.v5.missions.reviews||0)+1;
  if(state.analytics){const section=['alphabet','vocabulary','grammar','sentences','travel'].includes(String(options.section))?String(options.section):'';state.analytics.answered=Number(state.analytics.answered||0)+1;state.analytics[correct?'correct':'wrong']=Number(state.analytics[correct?'correct':'wrong']||0)+1;if(section)state.analytics[section]=Number(state.analytics[section]||0)+1;state.analytics.lastAnswerAt=Date.now();if(!state.analytics.firstStudyAt)state.analytics.firstStudyAt=Date.now();}
 if(state.questData?.daily&&state.questData?.weekly){state.questData.daily.answered=Number(state.questData.daily.answered||0)+1;state.questData.weekly.answered=Number(state.questData.weekly.answered||0)+1;if(correct){state.questData.daily.correct=Number(state.questData.daily.correct||0)+1;state.questData.weekly.correct=Number(state.questData.weekly.correct||0)+1;state.questData.daily.bestStreak=Math.max(Number(state.questData.daily.bestStreak)||0,state.streak);}if(review){state.questData.daily.reviews=Number(state.questData.daily.reviews||0)+1;state.questData.weekly.reviews=Number(state.questData.weekly.reviews||0)+1;}}
 let treasure=null,companion={extraXp:0,hintAwarded:0,shieldAwarded:0,reviewReward:0};if(correct){state.v5.missions.correct=Number(state.v5.missions.correct||0)+1;state.v5.totalCorrect=Number(state.v5.totalCorrect||0)+1;react('happy');companion=applyCompanionCorrectAnswer({stage},review);if(state.v5.totalCorrect%CHEST_CORRECT_INTERVAL===0){treasure={amount:chestRewardAmount(stage),stage,earnedAt:Date.now()};if(deferTreasure)state.v5.deferredTreasures.push(treasure);else grantTreasureReward(treasure);}}else react('sad');try{markPracticeToday();}catch{}save();try{updateSessionDashboard();}catch{}if(treasure&&!deferTreasure)showChest(treasure.amount);return {correct,stage,treasureAmount:Number(treasure?.amount)||0,treasureDeferred:!!treasure&&deferTreasure,totalCorrect:state.v5.totalCorrect,companion};
}
function grantExternalCourseReward(amount,stage=0,label='Course reward earned!'){
 ensureV5();amount=Math.max(0,Math.round(Number(amount)||0));stage=Math.max(0,Math.min(stages.length-1,Number(stage)||0));if(!amount)return 0;addStoneChange(amount,Math.min(gemTiers.length-1,stage+5));save();showChest(amount,1,label);return amount;
}
window.LanguageMinerEconomy=Object.freeze({recordCourseAnswer:recordExternalCourseAnswer,grantNuggets:grantExternalCourseReward,releaseTreasures:(announce=true,label='Course treasure received!')=>releaseDeferredTreasures(announce,label),balance:()=>totalStoneValue()});
function react(kind){document.querySelectorAll('.miner-avatar').forEach(a=>{a.dataset.reaction=kind;setTimeout(()=>{if(a.dataset.reaction===kind)delete a.dataset.reaction;},1100);});}
function decorateCharacters(){
 ensureV5();
 const tier=window.japaneseMinerSupporterTier?.()||0,fashion=effectiveCharacterFashion(tier);
 document.querySelectorAll('.miner-avatar').forEach(a=>{if(a.closest('.choice-avatar-preview,.fashion-avatar-preview'))return;a.dataset.jacket=fashion.jacket;a.dataset.gloves=fashion.gloves;a.dataset.shoes=fashion.shoes;});
 let pet=document.getElementById('v5CompanionFloat');const companion=tier>=2?COMPANIONS.find(x=>x.id===state.v5.companion):null,showLauncher=state.v6?.showFloatingCompanion!==false;
 if(companion&&companion.id!=='none'&&showLauncher){if(!pet){pet=document.createElement('button');pet.id='v5CompanionFloat';pet.className='v5-companion-float';pet.onclick=()=>openShop('companions');document.body.appendChild(pet);}pet.innerHTML=companionPortraitMarkup(companion,'float');pet.title=`${companion.name} · ${companionOutfitFor(companion).name} · Open companions`;pet.setAttribute('aria-label',`Equipped companion: ${companion.name}, wearing ${companionOutfitFor(companion).name}. Open companions.`);}else pet?.remove();
 document.querySelectorAll('.character-preview-card,.menu-avatar-pane').forEach(card=>{let display=card.querySelector('.character-companion-display');if(!companion||companion.id==='none'){display?.remove();card.classList.remove('has-equipped-companion');return;}card.classList.add('has-equipped-companion');if(!display){display=document.createElement('button');display.type='button';display.className='character-companion-display';display.onclick=()=>{if(typeof closeGameMenu==='function')closeGameMenu();openShop('companions');};card.appendChild(display);}display.innerHTML=`${companionPortraitMarkup(companion,'profile')}<strong>${esc(companion.name.replace(/ the .*/, ''))}</strong><small>${esc(companionOutfitFor(companion).name)}</small>`;display.title=`${companion.name}: ${companion.bonus}`;display.setAttribute('aria-label',`Equipped companion: ${companion.name}, wearing ${companionOutfitFor(companion).name}. Open companions shop.`);});
}
