function avatarForPreview(item){const clothingPreview=['shirt','pants'].includes(item.key),source=document.querySelector('.miner-avatar.large')||document.querySelector('.miner-avatar'),override=item.key==='accessory'?{accessories:[item.value],accessory:item.value}:item.type==='holiday'?{}:{[item.key]:item.value},markup=window.japaneseMinerCharacterMarkup?.('large',override,{hideJacket:clothingPreview,allowLockedPreview:item.key==='accessory',holidaySpecial:item.type==='holiday'?item.value:''});let avatar=null;if(markup){const shell=document.createElement('div');shell.innerHTML=markup;avatar=shell.firstElementChild;}else if(source)avatar=source.cloneNode(true);if(!avatar)return null;for(const key of ['jacket','gloves','shoes'])if(source?.dataset[key])avatar.dataset[key]=source.dataset[key];if(item.type==='holiday'&&item.holiday){Object.entries(item.holiday.outfit).forEach(([key,value])=>avatar.dataset[key]=value);avatar.dataset.holidaySpecial=item.holiday.id;}else{avatar.dataset.holidaySpecial='none';if(clothingPreview)avatar.dataset.jacket='none';if(item.key)avatar.dataset[item.key]=item.value;}avatar.classList.remove('mini');avatar.classList.add('large','preview-avatar');avatar.removeAttribute('id');avatar.dataset.previewKey=item.key;window.syncJapaneseMinerRenderedLayers?.(avatar);return avatar;}
