 status(){
  ensureV5();const session=activeSmartReviewSession(),due=dueSmartReviewQuestions(),total=Number(session?.questionIds?.length)||0,completed=Math.min(total,Math.max(0,Number(session?.index)||0));
  return {active:!!session,dueCount:due.length,total,completed,remaining:session?Math.max(0,total-completed):due.length,canStart:!!session||due.length>0};
 },
	 items(){
  ensureV5();const session=activeSmartReviewSession(),remainingIds=session?session.questionIds.slice(session.index).map(String):[],due=dueSmartReviewQuestions(),byId=new Map(due.map(question=>[String(question.id),question])),ordered=[];
  remainingIds.forEach(id=>{const question=byId.get(id);if(question){ordered.push(question);byId.delete(id);}});byId.forEach(question=>ordered.push(question));
  return ordered.map(question=>{const id=String(question.id),memory=state.v5.srs[id]||{};return{id,term:stripMarkup(question.displayChallenge||question.q||question.prompt||'Review item'),prompt:stripMarkup(question.prompt||''),answer:stripMarkup(question.a||''),stage:Math.max(0,Number(question.stage)||0),stageLabel:String(stages[Math.max(0,Number(question.stage)||0)]?.label||'Review'),reviewed:Math.max(0,Number(memory.repetitions)||0),dueAt:Number(memory.dueAt)||0,current:!!session&&String(session.questionIds[session.index])===id,inSession:remainingIds.includes(id)};});
	 },
