jlptSectionWorldLevels=function(stage,section){
 const spec=jlptSectionSpec(section),config=jlptSectionLessonConfig(section),levels=jlptSectionLevels(stage,section),selected=currentJlptSectionLevel(stage,section),quizCount=Math.floor(levels.length/2),quizMode=window.japaneseMinerQuizModeMarkup?.()||'';
 return `<div class="jlpt-vocabulary-panel jlpt-section-lessons"><header><div><strong>${spec.name} lessons</strong><small>Reach 75% in each lesson, then pass every two-lesson review quiz.</small></div><div class="jlpt-lesson-head-actions"><span>${levels.length} lessons · ${quizCount} quizzes</span>${quizMode}</div></header><div class="jlpt-vocabulary-grid">${levels.map((level,index)=>{const open=jlptSectionLevelUnlocked(stage,section,index),mastery=jlptSectionLevelMastery(stage,section,index),current=index===selected,complete=mastery>=JLPT_VOCABULARY_UNLOCK_MASTERY,card=`<button data-world-lesson-stage="${stage}" data-world-lesson-section="${section}" data-world-lesson-level="${index}" class="jlpt-vocabulary-level ${open?'open':'locked'} ${complete?'complete':''} ${current?'current':''}" ${open?'':'disabled'}><span>${open?index+1:'🔒'}</span><strong>Lesson ${index+1}</strong><small>${level.length} ${config.plural} · ${mastery}% mastery</small><i><b style="width:${mastery}%"></b></i></button>`;return `${card}${(index+1)%2===0?renderJlptReviewCheckpointCard(stage,section,index+1,true):''}`;}).join('')}</div></div>`;
};
